import { DurableObject } from 'cloudflare:workers';
import { parseCronExpression } from 'cron-schedule';

export class Counter extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS hits (at INTEGER NOT NULL)');
    ctx.blockConcurrencyWhile(async () => {
      if ((await ctx.storage.getAlarm()) === null) await this.armNext();
    });
  }

  async armNext() {
    const next = parseCronExpression('0 3 * * *').getNextDate(new Date());
    await this.ctx.storage.setAlarm(next.getTime());
  }

  async alarm() {
    await this.compact();
    await this.armNext();
  }

  async compact() {
    this.ctx.storage.sql.exec('DELETE FROM hits WHERE at < ?', Date.now() - 30 * 24 * 3600 * 1000);
  }
}

